UPDATE t_board
SET title            = #{title},
    contents         = #{contents},
    updated_datetime = Now(),
    updater_id       = #{updaterId}
WHERE board_idx = #{boardIdx}


UPDATE t_board
SET deleted_yn       = 'Y',
    updated_datetime = Now(),
    updater_id       = #{updaterId}
WHERE board_idx = #{boardIdx}
